methods.card_pool:
func card_pool(run: RunState, tier: String) -> Array:
	var base: Array = content.card_pools.get(tier, [])
	var out: Array = []
	for id_v: Variant in base:
		var id: String = str(id_v)
		if not _pool_open(run, content.pool_gate_cards, id):
			continue
		out.append(id)
	for unlock_v: Variant in run.unlocks:
		var unlock: String = str(unlock_v)
		if unlock.begins_with("card:"):
			var id: String = unlock.trim_prefix("card:")
			if content.cards.has(id) and content.cards[id].get("rarity") == tier and not out.has(id):
				out.append(id)
	return out

draw_callsites._apply_art_effect:
func _apply_art_effect(run: RunState, cb: CombatState, fx: Dictionary) -> void:
	var p: PlayerCombatant = cb.player
	var kind: String = str(fx.get("kind", ""))
	match kind:
		"dmg":
			for e: EnemyCombatant in cb.living_enemies():
				if not cb.over:
					hit_enemy(run, cb, e, _ji(fx["n"]), false)
		"status":
			var sid: String = str(fx["id"])
			var sn: int = _ji(fx["n"])
			if str(fx.get("who", "")) == "self":
				add_status_player(cb, sid, sn)
			else:
				for e: EnemyCombatant in cb.living_enemies():
					add_status_enemy(cb, e, sid, sn, run)
		"block":
			gain_block_player(cb, _ji(fx["n"]), false, run)
		"heal":
			heal_player(run, cb, _ji(fx["n"]))
		"energy":
			p.energy += _ji(fx["n"])
			cb.queue.append({"t": EventTypes.ENERGY, "n": p.energy})
		"draw":
			draw_cards(run, cb, _ji(fx["n"]))
		"chip":
			for e: EnemyCombatant in cb.living_enemies():
				apply_chips(run, cb, e, _ji(fx["n"]))
		"ember":
			gain_embers(run, cb, _ji(fx["n"]))
		_:
			push_error("CombatRules: unknown art effect kind %s" % kind)


