func _on_enemy_death(run: RunState, cb: CombatState, e: EnemyCombatant) -> void:
	e.hp = 0
	var smolder: int = _sget(e.statuses, "poison")  # capture before the vessel empties
	e.statuses = {}
	e.staggered = false
	cb.queue.append({"t": EventTypes.DIE, "idx": e.idx})
	# The death line rides right behind the die event (engine.js:1384-1385).
	var death_line_v: Variant = e.def.get("deathDialogue")
	if typeof(death_line_v) == TYPE_STRING and not str(death_line_v).is_empty():
		cb.queue.append({"t": EventTypes.VARIANT_DIALOGUE, "idx": e.idx,
			"text": str(death_line_v)})
	quests.on_enemy_death(run, e.def)
	run.stats["slain"] = _ji(run.stats.get("slain", 0)) + 1
	if e.elite:
		run.stats["elites"] = _ji(run.stats.get("elites", 0)) + 1
	if e.boss:
		run.stats["bosses"] = _ji(run.stats.get("bosses", 0)) + 1
	for o: EnemyCombatant in cb.enemies:
		if o.hp > 0:
			gain_embers(run, cb, 1)  # the fire inside spills to your lantern
			_jump_smolder(run, cb, e, smolder)
			if run.has_relic("reapersBell"):
				cb.player.energy += 1
				draw_cards(run, cb, 1)
				_proc(cb, "reapersBell")
				cb.queue.append({"t": EventTypes.ENERGY, "n": cb.player.energy})
			return
	_win_combat(run, cb)

draw_callsites._start_player_turn:
func _start_player_turn(run: RunState, cb: CombatState) -> void:
	if cb.over:
		return
	cb.turn += 1
	var p: PlayerCombatant = cb.player
	cb.queue.append({"t": EventTypes.TURN, "n": cb.turn})
	# Smolder ticks at the start of your turn.
	var poison: int = _sget(p.statuses, "poison")
	if poison > 0:
		damage_player(run, cb, poison, "poison")
		poison -= 1
		if poison == 0:
			p.statuses.erase("poison")
		else:
			p.statuses["poison"] = poison
		if cb.over:
			return
	if _sget(p.statuses, "barricade") == 0:
		p.block = 0
	var ritual: int = _sget(p.statuses, "ritual")
	if ritual > 0:
		add_status_player(cb, "str", ritual)
	var emberflow: int = _sget(p.statuses, "emberflow")
	if emberflow > 0:
		gain_embers(run, cb, emberflow)
	var energy: int = p.energy_max + _sget(p.statuses, "energized")
	if cb.turn == 1 and run.has_relic("emberLantern"):
		energy += 1
		_proc(cb, "emberLantern")
	p.energy = (p.energy if run.has_relic("frozenCore") else 0) + energy
	cb.first_card_played = false
	cb.queue.append({"t": EventTypes.ENERGY, "n": p.energy})
	var draws: int = 5 + _sget(p.statuses, "nightsight") \
		+ _ji(_omen_mods(run).get("drawDelta", 0))
	if cb.turn == 1 and run.has_relic("travelersPack"):
		draws += 2
		_proc(cb, "travelersPack")
	draw_cards(run, cb, maxi(1, draws))

methods.observed_factory:
static func simulate(content: ContentDB, aspect: String, seed: int, vow: int = 0,
		ban: PackedStringArray = PackedStringArray(), policy: Dictionary = {},
		random_build: bool = false, random_play: bool = false, mix: Dictionary = {},
		vigil: VigilState = null, strip_start_hex: bool = false) -> Dictionary:
	_probe = {}
	Pilot.set_ban(ban)
	Pilot.apply_policy(policy)
	Pilot.set_modes(random_build, random_play)
	var aspect_index: int = 1 if aspect == "ashwarden" else 0
	var profile: Dictionary = {
		"aspect": aspect_index, "vow": vow, "reveals": content.reveal_ids.duplicate(),
		"unlocks": ["aspect2"], "quests": {}, "shards": [], "lamplighter": false,
	}
	if vigil != null:
		profile["quests"] = vigil.quests.duplicate(true)
		profile["shards"] = vigil.shards.duplicate()
	var run: RunState = RunState.new_run(content, seed, "sim-%s-%d" % [aspect, seed], profile)
	if strip_start_hex:
		_strip_hex(run)
	_apply_ban(run)
	var game: GlassvowGame = preload("res://observed_game.gd").new(content, run)
	# Empty mix follows the live shipping overlay. Pass catalog `none` to measure
	# the penalty ladder without incentives.
	Incentives.apply(game.rewards, mix if not mix.is_empty() else Incentives.shipping(),
		vow)
	var fights: Array[Dictionary] = []
	var economy: Array[Dictionary] = []
	for _act: int in range(3):
		var map: WorldMap = WorldMap.benchmark(run)
		while not map.is_finished():
			var i: int = Pilot.choose_node(map, run)
			if not map.enter(i):
				return _finish(run, aspect, seed, "error", fights, "unreachable node", economy,
					vigil, content)
			var node: MapNode = map.current()
			_enter_node(run, node)
			if node.is_combat():
				var fight: Dictionary = _fight(game, node)
				_harvest_fight(game)
				fights.append(fight)
				if fight["result"] != "win":
					return _finish(run, aspect, seed,
						"stall" if fight["result"] == "stall" else "loss",
						fights, "", economy, vigil, content)
				if node.type == "boss" and run.act == 2:
					economy.append(_economy_row(run))
					return _finish(run, aspect, seed, "win", fights, "", economy, vigil, content)
				_claim_rewards(game, game.gen_combat_rewards(node.combat_kind(), game.cb.affix))
			else:
				_resolve_safe_node(game, node)
			map.clear_current()
			if node.type == "boss" and not run.is_final_act():
				economy.append(_economy_row(run))
				var offered: Array[String] = game.rewards.roll_boss_relics(run)
				for offered_id: String in offered:
					if offered_id == "hollowCrown":
						_bump("hollowCrownOffered")
				var relic: String = Pilot.choose_relic(offered, content, run.aspect, run.rng)
				if not relic.is_empty():
					if relic == "hollowCrown":
						_bump("hollowCrownPicked")
						_bump("maxHpLostToCrown", _ji(content.relic(&"hollowCrown").get("maxHpPenalty", 10)))
					game.rewards.gain_relic(run, relic)
				run.boss_relic_act = run.act
				run.start_next_act(content)
				break
	return _finish(run, aspect, seed, "error", fights, "run route exhausted", economy, vigil, content)

methods.vigil_refresh_unlocks:
func _refresh_unlocks(content: ContentDB, outcome: String) -> void:
	var thresholds: Dictionary = content.progression.get("revealThresholds", {})
	for id: String in thresholds:
		var trigger: Dictionary = thresholds[id]
		var reached: bool = (
			runs_played >= _ji(trigger["runsPlayed"]) if trigger.has("runsPlayed")
			else (_ji(deeds["wins"]) >= _ji(trigger["wins"]) if trigger.has("wins")
				else shards.size() >= _ji(trigger.get("shards", 999)))
		)
		if reached and not unlocks.has(id):
			unlocks.append(id)
	for deed_v: Variant in content.deeds.values():
		var deed: Dictionary = deed_v
		if _ji(deeds.get(str(deed.get("stat")), 0)) < _ji(deed.get("n", 0)):
			continue
		for unlock_v: Variant in deed.get("unlocks", []):
			var unlock: String = str(unlock_v)
			if not unlocks.has(unlock):
				unlocks.append(unlock)
	if _ji(deeds["wins"]) >= 1 and str(quests["paleOnes"]["state"]) == "dormant":
		quests["paleOnes"]["state"] = "armed"
	if outcome != "win":
		return
	var arm_wins: Array = content.progression.get("emberglass", {}).get("armWins", [])
	if not arm_wins.has(_ji(deeds["wins"])):
		return
	for id: String in QUEST_IDS:
		if id != "paleOnes" and str(quests[id]["state"]) == "dormant":
			quests[id]["state"] = "armed"
			if id == "eighthOmen":
				quests[id]["memory"]["dueIn"] = 2
			break
